    function render() {
      appRoot.innerHTML = App();

      const dialog = appRoot.querySelector("#delete-dialog");

      if (state.isDialogOpen && dialog) {
        const closeButton = appRoot.querySelector(".dialog-close");
        closeButton.focus();
      }
    }

    function openDialog() {
      state.isDialogOpen = true;
      render();
    }

    function closeDialog() {
      state.isDialogOpen = false;
      render();
