<body>
  <div id="app"></div>
  <script>
    const state = {
      isDialogOpen: false
    };

    const appRoot = document.getElementById("app");

    function Button({ label, className = "", type = "button", attributes = "" }) {
      const classes = className.trim();
      const attributeString = attributes ? ` ${attributes}` : "";
      return `<button type="${type}" class="${classes}"${attributeString}>${label}</button>`;
    }

    function Header() {
      return `
