              <rect width="640" height="480" rx="28" fill="url(#sky)" />
              <circle cx="494" cy="98" r="40" fill="#ffe7ba" opacity="0.85" />
              <path d="M0 360L112 258L176 302L248 210L338 320L420 196L530 332L640 248V480H0Z" fill="#111827" opacity="0.44" />
              <path d="M0 392L118 278L190 314L266 232L350 338L458 218L550 332L640 282V480H0Z" fill="url(#mountain)" />
              <path d="M0 420L140 344L246 392L342 324L468 404L640 322V480H0Z" fill="#070c14" />
              <rect x="70" y="88" width="150" height="88" rx="18" fill="rgba(255,255,255,0.16)" stroke="rgba(255,255,255,0.2)" />
              <text x="102" y="142" fill="#ffffff" font-size="28" font-family="Inter, sans-serif" font-weight="700">RAW</text>
            </svg>
          </div>
          <div class="image-caption">
            <div>
              <strong>Aurora Peak</strong>
              <span>4096 x 2731 px</span>
            </div>
            <span>Edited 2 hours ago</span>
