              className: "icon-button trigger",
              attributes: 'data-open-dialog aria-haspopup="dialog" aria-controls="delete-dialog"'
            })}
          </div>
        </section>
      `;
    }

    function ConfirmDialog() {
      const hiddenAttribute = state.isDialogOpen ? "" : "hidden";
      return `
        <div class="dialog-root" id="dialog-root" ${hiddenAttribute}>
          <div class="dialog-backdrop" data-close-dialog></div>
          <div class="dialog-container">
            <section
              class="dialog"
              id="delete-dialog"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
            >
              <button class="dialog-close" type="button" data-close-dialog aria-label="Close confirmation dialog">x</button>
              <div class="dialog-icon" aria-hidden="true">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                  <path d="M12 8v5m0 4h.01M10.29 3.86 1.82 18A2 2 0 0 0 3.53 21h16.94a2 2 0 0 0 1.71-3l-8.47-14.14a2 2 0 0 0-3.42 0Z" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </div>
              <h2 id="dialog-title">Delete this image?</h2>
              <p id="dialog-description">This will permanently remove <strong>Aurora Peak</strong> from your library. This action cannot be undone.</p>
              <div class="dialog-actions">
                ${Button({
                  label: "Keep image",
                  className: "button button-secondary",
                  attributes: 'data-close-dialog'
                })}
                ${Button({
                  label: "Delete permanently",
                  className: "button button-danger"
                })}
              </div>
            </section>
          </div>
        </div>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          <div class="preview-layout">
            ${Header()}
            ${PreviewCard()}
          </div>
          ${ConfirmDialog()}
        </main>
      `;
    }

    function render() {
      appRoot.innerHTML = App();

      const dialog = appRoot.querySelector("#delete-dialog");

      if (state.isDialogOpen && dialog) {
        const closeButton = appRoot.querySelector(".dialog-close");
        closeButton.focus();
      }
    }

    function openDialog() {
      state.isDialogOpen = true;
      render();
    }

    function closeDialog() {
      state.isDialogOpen = false;
      render();
      const trigger = appRoot.querySelector(".trigger");
      if (trigger) {
        trigger.focus();
      }
    }

    function handleEscape(event) {
      if (event.key === "Escape" && state.isDialogOpen) {
        closeDialog();
      }
    }

    appRoot.addEventListener("click", (event) => {
      const control = event.target.closest("[data-open-dialog], [data-close-dialog]");
      if (!control) {
        return;
      }

      if (control.hasAttribute("data-open-dialog")) {
        openDialog();
        return;
      }

      closeDialog();
    });

    document.addEventListener("keydown", handleEscape);

    render();
  </script>
